// This file is generated by AI.

// `sameGitStatus` 的测试。
//
// 判据是"内容没变就不通知 store", 守的是"闪"这条线: 自动保存落盘后必然触发 `git status` 重跑,
// 每次都下发新对象会让色块、仓库页列表、状态栏全部重画一遍。
//
// 纯函数, 不依赖 Monaco / Tauri。

import { describe, expect, it } from 'vitest';

import { sameGitStatus } from '../src/git/compare';
import type { GitStatus } from '../src/commands/git';

function status(patch: Partial<GitStatus> = {}): GitStatus {
  return {
    initialized: true,
    branch: 'main',
    staged: [],
    unstaged: [],
    identity: { name: 'me', email: 'me@example.com' },
    ...patch,
  };
}

describe('sameGitStatus', () => {
  it('内容相同 (新对象) 算没变', () => {
    expect(sameGitStatus(status(), status())).toBe(true);
  });

  it('null 与 undefined 等价', () => {
    expect(sameGitStatus(null, null)).toBe(true);
    expect(sameGitStatus(undefined, undefined)).toBe(true);
    expect(sameGitStatus(null, undefined)).toBe(true);
  });

  it('有值与 null 互相算变了', () => {
    expect(sameGitStatus(status(), null)).toBe(false);
    expect(sameGitStatus(null, status())).toBe(false);
  });

  it('文件统计变化算变了（增删行数）', () => {
    const a = status({ unstaged: [{ path: 'game/scene/a.txt', status: 'M', additions: 1, deletions: 0 }] });
    const b = status({ unstaged: [{ path: 'game/scene/a.txt', status: 'M', additions: 2, deletions: 0 }] });
    expect(sameGitStatus(a, b)).toBe(false);
  });

  it('路径 / 状态字母 / 顺序 变化都算变了', () => {
    const one = status({ unstaged: [{ path: 'a.txt', status: 'M', additions: 1, deletions: 1 }] });
    const renamed = status({ unstaged: [{ path: 'b.txt', status: 'M', additions: 1, deletions: 1 }] });
    const letter = status({ unstaged: [{ path: 'a.txt', status: 'A', additions: 1, deletions: 1 }] });
    expect(sameGitStatus(one, renamed)).toBe(false);
    expect(sameGitStatus(one, letter)).toBe(false);

    const first = status({
      staged: [
        { path: 'a.txt', status: 'M', additions: 0, deletions: 0 },
        { path: 'b.txt', status: 'M', additions: 0, deletions: 0 },
      ],
    });
    const reversed = status({
      staged: [
        { path: 'b.txt', status: 'M', additions: 0, deletions: 0 },
        { path: 'a.txt', status: 'M', additions: 0, deletions: 0 },
      ],
    });
    expect(sameGitStatus(first, reversed)).toBe(false);
  });

  it('暂存与未暂存是两个列表, 互不抵消', () => {
    const file = { path: 'a.txt', status: 'M' as const, additions: 1, deletions: 1 };
    expect(sameGitStatus(status({ staged: [file] }), status({ unstaged: [file] }))).toBe(false);
  });

  it('初始化状态 / 分支 / 提交身份 变化算变了', () => {
    expect(sameGitStatus(status(), status({ initialized: false }))).toBe(false);
    expect(sameGitStatus(status(), status({ branch: 'dev' }))).toBe(false);
    expect(sameGitStatus(status(), status({ identity: null }))).toBe(false);
    expect(sameGitStatus(status(), status({ identity: { name: 'me', email: 'other@example.com' } }))).toBe(false);
  });

  it('列表长度变化算变了', () => {
    const a = status({ unstaged: [{ path: 'a.txt', status: 'M', additions: 0, deletions: 0 }] });
    expect(sameGitStatus(a, status())).toBe(false);
    expect(sameGitStatus(status(), a)).toBe(false);
  });
});
